@startuml

class OOBank {}

class Branch {
  + address : string
  + branchNumber : int
}

class Division {}

class Subdivision {}

class Employee {
  + name : string
}

class Customer {
  + name : string
}

class Account {
  + accountNumber : int
  + balance : double
  + creditOrOverdraftLimit : double
  + interestRate : double
  + monthlyFee : double
}

class MortgageAccount extends Account {
  + propertyCollateral : string
}

class CheckingAccount extends Account {}

class CreditCardAccount extends Account {
  + expiryDate : date
}

class SecondaryCard {}

class Privilege {}

class Manager {}

Manager "1" -- "1" Division : manages

Division "1" -- "*" Subdivision
Subdivision "1" -- "*" Branch
Division "1" -- "*" Employee

Customer "1" -- "0..1" Employee : personal banker
Customer "*" -- "*" Account : opens
Account "*" -- "*" Privilege : has

CreditCardAccount "1" -- "*" SecondaryCard : has

@enduml

